llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Absolute oral bioavailability of bumetanide was 0.86 ± 0.13 in normal subjects after a 1 mg oral tablet compared with IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Absolute oral bioavailability of levodopa from standard Sinemet was 80.4 ± 18.9 in healthy young volunteers after an overnight fast, well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Absolute oral bioavailability of mosliciguat was 23.1% in healthy male volunteers for a 1000 µg oral solution versus 100 µg IV, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied high-assay-transfer evidence molecules with numeric absolute oral bioavailability data are at or above 20%, with most well above the threshold. The only sub-threshold value is a low-quality azosemide estimate, outweighed by its absolute fasting estimate of 20.4% and by numerous high F records. High oral bioavailability is therefore better supported.",
  "evidence_gaps": [
    "Azosemide has a conflicting low-quality estimate of 10% from urinary excretion in different patients (C41), while its absolute fasting estimate is 20.4% (C34), introducing some uncertainty for that molecule.",
    "Y-700 (C36) is only qualitatively described as having high oral bioavailability without a numeric threshold-relevant measurement.",
    "GDC-0810 (C26) is a PBPK-predicted F of approximately 45% with no clinical data available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

